# The SIMD methods of OrdinaryDiffEqSIMDRK evaluate their stages in pairs or
# quadruples; their tableau is that of an ordinary FSAL Runge-Kutta method
# (A from a{i}_{j}, b the last row, c, and btilde), built here from the
# constants above.
.simd_tableau <- function(name, order) {
  x <- .SIMD_RK[[name]]
  an <- grep("^a[0-9]+_[0-9]+$", names(x), value = TRUE)
  ii <- as.integer(sub("_.*$", "", sub("^a", "", an)))
  jj <- as.integer(sub("^a[0-9]+_", "", an))
  S <- max(ii)
  A <- matrix(0, S, S)
  for (k in seq_along(an)) A[ii[k], jj[k]] <- x[[an[k]]]
  cc <- numeric(S)
  for (nm in grep("^c_[0-9]+$", names(x), value = TRUE)) cc[as.integer(sub("^c_", "", nm))] <- x[[nm]]
  cc[S] <- 1
  bt <- numeric(S)
  for (nm in grep("^btilde_[0-9]+$", names(x), value = TRUE)) bt[as.integer(sub("^btilde_", "", nm))] <- x[[nm]]
  list(s = S, A = as.numeric(t(A)), b = A[S, ], c = cc, btilde = bt, order = order, adaptive_order = order - 1,
       adaptive = TRUE, nonlinear_est = FALSE, qmax = 10, qmin = 1 / 5, gamma = 0.9,
       beta1 = 7 / (10 * order), beta2 = 2 / (5 * order), controller = "PIController")
}


