#' SIMD and tableau driven explicit Runge-Kutta methods
#'
#' `MER5v2()`, `MER6v2()` and `RK6v4()` are the explicit methods of
#' OrdinaryDiffEqSIMDRK (orders 5, 6 and 6), whose stages Julia evaluates in
#' SIMD pairs or quadruples; R evaluates them in turn, with the same tableau.
#' `ExplicitRK(tableau)` runs any explicit Runge-Kutta tableau built by
#' `ExplicitRKTableau(A, c, alpha, order, alphaEEst, adaptiveorder, fsal)`
#' (`alpha` the weights of the solution, `alphaEEst` those of the embedded
#' solution); the default is OrdinaryDiffEqExplicitRK's Tsitouras 5/4
#' tableau `constructTsit5ExplicitRK()`.
#'
#' @param tableau An `ExplicitRKTableau`.
#' @param A,c,alpha,alphaEEst Tableau entries.
#' @param order,adaptiveorder Orders of the method and its estimate.
#' @param fsal Whether the last stage is the first of the next step.
#' @param stage_limiter,step_limiter,thread See [explicit_rk_methods].
#' @return An algorithm or a tableau.
#' @examples
#' prob <- ODEProblem(function(u, p, t) -u, 1, c(0, 1))
#' solve(prob, MER5v2())(1)
#' solve(prob, ExplicitRK())(1)
#' @name simd_and_tableau_rk
NULL

#' @rdname simd_and_tableau_rk
#' @export
MER5v2 <- function(stage_limiter = NULL, step_limiter = NULL, thread = NULL)
  .erk_alg("MER5v2", stage_limiter, step_limiter, tableau = .simd_tableau("MER5v2", 5))
#' @rdname simd_and_tableau_rk
#' @export
MER6v2 <- function(stage_limiter = NULL, step_limiter = NULL, thread = NULL)
  .erk_alg("MER6v2", stage_limiter, step_limiter, tableau = .simd_tableau("MER6v2", 6))
#' @rdname simd_and_tableau_rk
#' @export
RK6v4 <- function(stage_limiter = NULL, step_limiter = NULL, thread = NULL)
  .erk_alg("RK6v4", stage_limiter, step_limiter, tableau = .simd_tableau("RK6v4", 6))

#' @rdname simd_and_tableau_rk
#' @export
ExplicitRKTableau <- function(A, c, alpha, order, alphaEEst = NULL, adaptiveorder = 0, fsal = FALSE)
  structure(list(A = as.matrix(A), c = as.numeric(c), alpha = as.numeric(alpha),
                 alphaEEst = if (!is.null(alphaEEst)) as.numeric(alphaEEst), stages = length(c), order = order,
                 adaptiveorder = adaptiveorder, fsal = fsal), class = c("ExplicitRKTableau", "Tableau"))

#' @rdname simd_and_tableau_rk
#' @export
constructTsit5ExplicitRK <- function() {
  x <- .TSIT5_EXPLICITRK$Tsit5ExplicitRK
  ExplicitRKTableau(x$A, x$c, x$alpha, x$order, x$alphaEEst, x$adaptiveorder, TRUE)
}

#' @rdname simd_and_tableau_rk
#' @export
ExplicitRK <- function(tableau = constructTsit5ExplicitRK()) {
  # perform_step! of ExplicitRKConstantCache: with a FSAL tableau the next
  # first stage is the last stage, evaluated at u + dt sum_j A[s, j] k_j
  A <- tableau$A; cc <- tableau$c; al <- tableau$alpha; s <- tableau$stages
  bt <- if (!is.null(tableau$alphaEEst)) al - tableau$alphaEEst
  fsal <- isTRUE(tableau$fsal)
  step <- function(ctx, t, u, dt, cache) {
    f <- ctx$f; p <- ctx$p
    K <- matrix(0, length(u), s)
    K[, 1L] <- cache$fsal %||% f(u, p, t)
    for (i in seq_len(s)[-1L])
      K[, i] <- f(u + dt * as.numeric(K[, seq_len(i - 1L), drop = FALSE] %*% A[i, seq_len(i - 1L)]), p, t + cc[i] * dt)
    unew <- u + dt * as.numeric(K %*% al)
    fl <- if (fsal) K[, s] else f(unew, p, t + dt)
    res <- list(u = unew, k = list(K[, 1L], fl), cache = list(fsal = fl), nf = s - 1L + (!fsal))
    if (!is.null(bt)) res$err <- dt * as.numeric(K %*% bt)
    res
  }
  .new_alg("ExplicitRK", tableau$order, adaptive = !is.null(bt), step = step, interp = .hermite_interp,
           init = function(ctx, t, u) list(), adaptive_order = tableau$adaptiveorder, tableau = tableau)
}
